INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('8912117e-8766-4d7f-a01e-9fe9d2fff499', 'Platform service down → incident', 'Open an incident when the platform SMS, BD Courier or PBX gateway stops working.', 'service_down', '{"minutes":10}', '[{"type":"create_incident","severity":"HIGH"},{"type":"notify_staff","action":"manage","module":"health","severity":"CRITICAL"}]', 1, 60, 25, NULL, NULL, NULL, NULL, '2026-10-22T01:22:34.306Z', NULL, '2026-10-22T01:22:34.306Z');
